#undef CHECK_KNULL
#define CHECK_KNULL(ptr) if (!ptr) { ffprintk("%s is Null\n", #ptr); ret = RET_ERROR; break; }

#undef PE_CHECK_NULL_PARAM
#define PE_CHECK_NULL_PARAM(_ret, _param)	\
	 if (!(_param)) { ffprintk("%s is Null\n", #_param); _ret = RET_ERROR; break; }

