/**
 * set noise reduction common parameter
 * @param   *param [in] void
 * @return  OK if success, ERROR otherwise.
 * @see		func. description
 * @author
 */
int KWRAP_PE_CheckTnrCmnParam(void *param)
{
	int ret = RET_OK;
	#ifdef PE_KWRAP_CHK_VALID_WIN_ID
	static UINT32 chk = 0x0;
	#endif
	//UINT8 *pd;
	LX_PE_NRD_TNR_CMN_T *ppp = param;
	if (PE_KDRV_VER_E60 || PE_KDRV_VER_O20)
	{
		LX_PE_NRD_TNR1_CMN_T *pp = NULL;
		#ifdef PE_KWRAP_CHK_VALID_WIN_ID
		static LX_PE_NRD_TNR1_CMN_T prev[LX_PE_WIN_NUM];
		#endif
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			pp = (LX_PE_NRD_TNR1_CMN_T *)ppp->data;
			KWRAP_PE_PrintTnrCmnParam((void*)pp);
			#ifdef PE_KWRAP_CHK_VALID_WIN_ID
			PE_KWRAP_CHECK_CMN_WINID(LX_PE_NRD_TNR1_CMN_T, NRD);
			ppp->win_id = pp->win_id;
			#endif
		}while (0);
	}
	else if (PE_KDRV_VER_M19 || PE_KDRV_VER_O18)
	{
		LX_PE_NRD_TNR8_CMN_T *pp = NULL;
		#ifdef PE_KWRAP_CHK_VALID_WIN_ID
		static LX_PE_NRD_TNR8_CMN_T prev[LX_PE_WIN_NUM];
		#endif
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			pp = (LX_PE_NRD_TNR8_CMN_T *)ppp->data;
			KWRAP_PE_PrintTnrCmnParam((void*)pp);
			#ifdef PE_KWRAP_CHK_VALID_WIN_ID
			PE_KWRAP_CHECK_CMN_WINID(LX_PE_NRD_TNR8_CMN_T, NRD);
			ppp->win_id = pp->win_id;
			#endif
		}while (0);
	}
	return ret;
}

int KWRAP_PE_SetTnrCmnBspDB(PE_KWRAP_CTRL_T *param)
{
	int ret = RET_OK;
	UINT32 param_data = 0;
	LX_PE_NRD_TNR_CMN_T pstParam;
	LX_PE_DBTYPE *dbtype = param->st_data;
	//UINT8 *pd;}
	if (PE_KDRV_VER_E60 || PE_KDRV_VER_O20)
	{
		LX_PE_NRD_TNR1_CMN_T ctrl;
		LX_PE_NRD_TNR1_CMN_T *pp = &ctrl;
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			param_data = (param->data<PE_KWRAP_NRD_NUM)? \
				param->data:PE_KWRAP_NRD_OFF;
			memcpy(&ctrl, &(g_pe_kwrap_p_tnr1_drvsetting_cmn[param_data]), sizeof(LX_PE_NRD_TNR1_CMN_T));
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"val:%d, dbtype:%d\n",\
				ctrl.win_id, \
				param->data, *dbtype);
			KWRAP_PE_PrintTnrCmnParam((void*)pp);
			//memcpy(ctrl, param, sizeof(LX_PE_WIN_ID));
			pstParam.win_id = ctrl.win_id;
			pstParam.oper = (UINT32)(*dbtype);
			pstParam.size = sizeof(LX_PE_NRD_TNR1_CMN_T);
			pstParam.data = (UINT32 *)&ctrl;
			ret = KWRAP_PE_SetTnrCmnParam(&pstParam);
			PE_CHECK_CODE(ret!=RET_OK, break, \
				"[%s,%d]KWRAP_PE_SetDnrCmnParam.\n", __F__, __L__);
		}while (0);
	}
	else if(PE_KDRV_VER_M17)
	{
		LX_PE_NRD_DNR8_CMN_T ctrl;
		ret = KWRAP_PE_SetDefaultParam(param, \
			PE_KWRAP_DFLT_PARAM_DNR_CMN, (void *)&ctrl, __F__, __L__);
	}
	else
	{
		PE_KWRAP_NOTI_NOT_SUPPORTED();
	}
	return ret;
}
