int KWRAP_PE_SetTnrDetailBspDB(PE_KWRAP_CTRL_T *param)
{
	int ret = RET_OK;
	UINT32 param_data = 0;
	LX_PE_NRD_TNR_DETAIL_T pstParam;
	LX_PE_DBTYPE *dbtype = param->st_data;
	__attribute__((unused)) UINT8 *pd;
	if (PE_KDRV_VER_O18)
	{
		LX_PE_NRD_TNR7_DETAIL_T ctrl;
		LX_PE_NRD_TNR7_DETAIL_T *pp = &ctrl;		
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			param_data = (param->data<PE_KWRAP_NRD_NUM)? \
				param->data:PE_KWRAP_NRD_OFF;			
			memcpy(&ctrl, &(g_pe_kwrap_p_tnr7_detail[param_data]), sizeof(LX_PE_NRD_TNR7_DETAIL_T));
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"val:%d, dbtype:%d\n",\
				ctrl.win_id, \
				param->data, *dbtype);
			pd = (UINT8 *)pp->tnr0___ma;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr0___ma    [00]0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1]);

			pd = (UINT8 *)pp->tnr0___me;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr0___me	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr0___me	  [10]0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10]);

			pd = (UINT8 *)pp->tnr0__mlb;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr0__mlb	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr0__mlb	  [10]0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12]);

			pd = (UINT8 *)pp->tnr0___mc;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr0___mc    [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr0___mc    [10]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12], pd[13], pd[14]);

			pd = (UINT8 *)pp->tnr0_blnd;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr0_blnd	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr0_blnd	  [10]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr0_blnd	  [20]0x%02X,0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12], pd[13], pd[14], pd[15], pd[16], pd[17], pd[18], pd[19],\
				pd[20], pd[21], pd[22], pd[23]);
			//memcpy(ctrl, param, sizeof(LX_PE_WIN_ID));
			pstParam.win_id = ctrl.win_id;
			pstParam.oper = (UINT32)(*dbtype);
			pstParam.size = sizeof(LX_PE_NRD_TNR7_DETAIL_T);
			pstParam.data = (UINT32 *)&ctrl;
			ret = KWRAP_PE_SetTnrDetailParam(&pstParam);
			PE_CHECK_CODE(ret!=RET_OK, break, \
				"[%s,%d]KWRAP_PE_SetDnrDetailParam.\n", __F__, __L__);
		}while (0);
	}
	else if(PE_KDRV_VER_M17)
	{
		LX_PE_NRD_DNR8_CMN_T ctrl;
		ret = KWRAP_PE_SetDefaultParam(param, \
			PE_KWRAP_DFLT_PARAM_DNR_CMN, (void *)&ctrl, __F__, __L__);
	}
	else
	{
		PE_KWRAP_NOTI_NOT_SUPPORTED();
	}
	return ret;
}
