{
	int ret = RET_OK;
	UINT32 param_data = 0;
	if (PE_KDRV_VER_O18)
	{
		const LX_PE_NRD_TNR2ND1_CMN_T *pp=NULL;
		UINT32 *pd;
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			PE_CHECK_NULL_PARAM(ret, param->st_data);
			param_data = (param->data<PE_KWRAP_NRD_NUM)? \
				param->data:PE_KWRAP_NRD_OFF;
			pp = &(g_pe_kwrap_p_tnr2nd_cmn[param_data]);
			memcpy(param->st_data, pp, sizeof(LX_PE_NRD_TNR2ND1_CMN_T));
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]tnr_en:%d\n", pp->win_id, pp->tnr1___en);
			pd = (UINT32 *)pp->tnr1__lut;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1__lut[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
				"tnr1__lut[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n", \
				pp->win_id, \
				pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
				pd[8],  pd[9],  pd[10], pd[11],pd[12], pd[13], pd[14], pd[15]);
			pd = (UINT32 *)pp->tnr1_gain;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr_lut_gain[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X\n",\
				pp->win_id, \
				pd[0],  pd[1],  pd[2],  pd[3], pd[4]);
			pd = (UINT32 *)pp->tnr1_buff;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1_buff[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
				"tnr1_buff[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
				"tnr1_buff[20]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
				"tnr1_buff[30]0x%08X,0x%08X\n",\
				pp->win_id, \
				pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
				pd[8],  pd[9],  pd[10], pd[11],	pd[12], pd[13], pd[14], pd[15], \
				pd[16],  pd[17],  pd[18],  pd[19], pd[20],  pd[21],  pd[22],  pd[23], \
				pd[24],  pd[25],  pd[26],  pd[27], pd[28],  pd[29],  pd[30],  pd[31]);
		}while (0);
	}
	else
	{
		PE_KWRAP_NOTI_NOT_SUPPORTED();
	}
	return ret;
}

/**
 * set noise reduction common parameter
 * @param   *param [in] void
 * @return  OK if success, ERROR otherwise.
 * @see		func. description
 * @author
 */
int KWRAP_PE_CheckTnr2ndCmnParam(void *param)
{
	int ret = RET_OK;
	#ifdef PE_KWRAP_CHK_VALID_WIN_ID
	static UINT32 chk = 0x0;
	#endif
	UINT32 *pd;
	LX_PE_NRD_TNR2ND_CMN_T *ppp = param;
	if (PE_KDRV_VER_O20)
	{
		LX_PE_NRD_TNR2ND2_CMN_T *pp = NULL;
		#ifdef PE_KWRAP_CHK_VALID_WIN_ID
		static LX_PE_NRD_TNR2ND2_CMN_T prev[LX_PE_WIN_NUM];
		#endif
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			pp = (LX_PE_NRD_TNR2ND2_CMN_T *)ppp->data;
			pd = (UINT32 *)pp->tnr1__lut;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0__lut[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0__lut[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n", \
			pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
			pd[8],  pd[9],  pd[10], pd[11],pd[12], pd[13], pd[14], pd[15]);
			pd = pp->tnr1_gain;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0_gain[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X\n",\
			pd[0],  pd[1],  pd[2],  pd[3], pd[4]);
			pd = pp->tnr1_buff;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0_buff[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0_buff[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X\n",\
			pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
			pd[8],  pd[9],  pd[10], pd[11],	pd[12], pd[13], pd[14]);
			#ifdef PE_KWRAP_CHK_VALID_WIN_ID
			PE_KWRAP_CHECK_CMN_WINID(LX_PE_NRD_TNR2ND2_CMN_T, NRD);
			ppp->win_id = pp->win_id;
			#endif
		}while (0);
	}
	return ret;
}

int KWRAP_PE_SetTnr2ndCmnBspDB(PE_KWRAP_CTRL_T *param)
{
	int ret = RET_OK;
	UINT32 param_data = 0;
	LX_PE_NRD_TNR2ND_CMN_T pstParam;
	LX_PE_DBTYPE *dbtype = param->st_data;
	__attribute__((unused)) UINT8 *pd;
	if (PE_KDRV_VER_O18)
	{
		LX_PE_NRD_TNR2ND1_CMN_T ctrl;	
		LX_PE_NRD_TNR2ND1_CMN_T *pp = &ctrl;	
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			param_data = (param->data<PE_KWRAP_NRD_NUM)? \
				param->data:PE_KWRAP_NRD_OFF;			
			memcpy(&ctrl, &(g_pe_kwrap_p_tnr2nd_cmn[param_data]), sizeof(LX_PE_NRD_TNR2ND1_CMN_T));
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"val:%d, dbtype:%d\n",\
				ctrl.win_id, \
				param->data, *dbtype);
			pd = (UINT8 *)pp->tnr1__lut;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0__lut[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0__lut[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n", \
			pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
			pd[8],  pd[9],  pd[10], pd[11],pd[12], pd[13], pd[14], pd[15]);
			pd = (UINT8 *)pp->tnr1_gain;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0_gain[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X\n",\
			pd[0],  pd[1],  pd[2],  pd[3], pd[4]);
			pd = (UINT8 *)pp->tnr1_buff;
			PE_KWRAP_DBG_PRINT(NRD, \
			"tnr0_buff[00]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0_buff[10]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0_buff[20]0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,0x%08X,\n"\
			"tnr0_buff[30]0x%08X,0x%08X\n",\
			pd[0],  pd[1],  pd[2],  pd[3], pd[4],  pd[5],  pd[6],  pd[7], \
			pd[8],  pd[9],  pd[10], pd[11],	pd[12], pd[13], pd[14], pd[15], \
			pd[16],  pd[17],  pd[18],  pd[19], pd[20],  pd[21],  pd[22],  pd[23], \
			pd[24],  pd[25],  pd[26],  pd[27], pd[28],  pd[29],  pd[30],  pd[31]);
			//memcpy(ctrl, param, sizeof(LX_PE_WIN_ID));
			pstParam.win_id = ctrl.win_id;
			pstParam.oper = (UINT32)(*dbtype);
			pstParam.size = sizeof(LX_PE_NRD_TNR2ND1_CMN_T);
			pstParam.data = (UINT32 *)&ctrl;
			ret = KWRAP_PE_SetTnrCmnParam(&pstParam);
			PE_CHECK_CODE(ret!=RET_OK, break, \
				"[%s,%d]KWRAP_PE_SetDnrCmnParam.\n", __F__, __L__);
		}while (0);
	}
	else if(PE_KDRV_VER_M17)
	{
		LX_PE_NRD_DNR8_CMN_T ctrl;
		ret = KWRAP_PE_SetDefaultParam(param, \
			PE_KWRAP_DFLT_PARAM_DNR_CMN, (void *)&ctrl, __F__, __L__);
	}
	else
	{
		PE_KWRAP_NOTI_NOT_SUPPORTED();
	}
	return ret;
}
/**
 * get temporal noise reduction detail default settings
 *	- input data : see PE_KWRAP_NRD_FMT_TYPE
 *
 * @param   *param [in/out] PE_KWRAP_CTRL_T
 * @return  OK if success, ERROR otherwise.
 * @see		func. description
 * @author
 */
int KWRAP_PE_GetTnr2ndDetailDefaultSettings(PE_KWRAP_CTRL_T *param)
{
	int ret = RET_OK;
	UINT32 param_data = 0;
	__attribute__((unused)) UINT8 *pd;
	if (PE_KDRV_VER_O18)
	{
		const LX_PE_NRD_TNR2ND1_DETAIL_T *pp=NULL;
		do {
			PE_CHECK_NULL_PARAM(ret, param);
			PE_CHECK_NULL_PARAM(ret, param->st_data);
			param_data = (param->data<PE_KWRAP_NRD_FMT_NUM)? \
				param->data:PE_KWRAP_NRD_FMT_SD;
			pp = &(g_pe_kwrap_p_tnr2nd_detail[param_data]);
			memcpy(param->st_data, pp, sizeof(LX_PE_NRD_TNR2ND1_DETAIL_T));
			pd = (UINT8 *)pp->tnr1__ctl;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1__ctl    [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1__ctl    [10]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1__ctl    [20]0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12], pd[13], pd[14], pd[15], pd[16], pd[17], pd[18], pd[19],\
				pd[20]);
			pd = (UINT8 *)pp->tnr1___ma;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1___ma    [00]0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1]);
				
			pd = (UINT8 *)pp->tnr1___me;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1___me	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1___me	  [10]0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10]);

			pd = (UINT8 *)pp->tnr1__mlb;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1__mlb	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1__mlb	  [10]0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12]);

			pd = (UINT8 *)pp->tnr1___mc;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1___mc    [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1___mc    [10]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12], pd[13], pd[14]);

			pd = (UINT8 *)pp->tnr1_blnd;
			PE_KWRAP_DBG_PRINT(NRD, \
				"[%d]:\n"\
				"tnr1_blnd	  [00]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1_blnd	  [10]0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,0x%02X,\n"\
				"tnr1_blnd	  [20]0x%02X,0x%02X,0x%02X,0x%02X,\n",\
				pp->win_id, \
				pd[0], pd[1], pd[2], pd[3], pd[4], pd[5], pd[6], pd[7], pd[8], pd[9],\
				pd[10], pd[11], pd[12], pd[13], pd[14], pd[15], pd[16], pd[17], pd[18], pd[19],\
				pd[20], pd[21], pd[22], pd[23]);
		}while (0);
	}
	else
	{
		PE_KWRAP_NOTI_NOT_SUPPORTED();
	}
	return ret;
}

