				PE_KWRAP_INTERPOL_32BIT(ctrl, p_data_tbl, PE_KWRAP_SHP_STEP, UINT8, shp_ui_sqm_vsd[18]);
				PE_KWRAP_INTERPOL_32BIT(ctrl, p_data_tbl, PE_KWRAP_SHP_STEP, UINT8, shp_ui_sqm_vsd[19]);
